import React, { useEffect, useRef, useState } from 'react';
import './App.css';

export interface Payment {
  id: number;
  amountCents: number;
}

export const ITEM_COUNT = 10000;
export const ROW_HEIGHT = 36;
export const VIEWPORT_HEIGHT = 360;
export const VISIBLE_ROWS = VIEWPORT_HEIGHT / ROW_HEIGHT;
export const OVERSCAN = 5;
export const POOL_SIZE = VISIBLE_ROWS + 2 * OVERSCAN;

/** Ten thousand payments, the same on every run. */
export const PAYMENTS: Payment[] = Array.from({ length: ITEM_COUNT }, (_, index) => ({
  id: index + 1,
  amountCents: ((index + 1) * 2654435761) % 100000,
}));

const numberFormat = new Intl.NumberFormat('en-US');
const moneyFormat = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
export const formatNumber = (value: number) => numberFormat.format(value);
export const formatMoney = (cents: number) => moneyFormat.format(cents / 100);

/**
 * Given: counts the row nodes ever created inside the list, so the recycling check can read it. Keep
 * `ref={listRef}` on `.viewport` and `ref={meterRef}` on `.row-meter`.
 */
function useRowNodeMeter() {
  const listRef = useRef<HTMLDivElement>(null);
  const meterRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const list = listRef.current;
    const meter = meterRef.current;
    if (!list || !meter) return;
    const seen = new WeakSet<Element>();
    let created = 0;
    const note = (node: Node) => {
      if (!(node instanceof Element)) return;
      const rows = node.matches('.row') ? [node] : Array.from(node.querySelectorAll('.row'));
      for (const row of rows) {
        if (seen.has(row)) continue;
        seen.add(row);
        created += 1;
      }
    };
    const show = () => {
      meter.textContent = `${formatNumber(created)} row nodes created`;
    };
    note(list);
    show();
    const observer = new MutationObserver((records) => {
      for (const record of records) record.addedNodes.forEach(note);
      show();
    });
    observer.observe(list, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, []);
  return { listRef, meterRef };
}

// TODO Task 1: render a window instead of every row. Keep POOL_SIZE `.row` elements: start OVERSCAN rows above the
//              first visible row, clamped so the window stays inside the list. Keep the spacer at the full height,
//              keep each row's translateY offset, and give rows aria-posinset and aria-setsize.
// TODO Task 2: set state in the viewport's scroll handler itself (the check frame runs no animation frames, so a
//              requestAnimationFrame-batched update never lands there), render the rows in that same update, and
//              show the ten rows from the first visible one in `.range`: `Showing 1,001–1,010 of 10,000` (en dash).
//              The first visible row is the one at the top edge, unless less than half a pixel of it is left.
// TODO Task 3: make `.go` scroll the list so payment N is the first visible row (9,991 and up show the last page),
//              set the window in the same handler, and say `Jumped to payment 4,821.` in `.jump-status`. For
//              anything but digits from 1 up, leave the list where it is and say
//              `Enter a whole payment number from 1 to 10,000.`
// TODO Task 4: recycle the row nodes: scrolling should reuse the same POOL_SIZE elements, so `.row-meter` keeps
//              reading `20 row nodes created`. Keep the role, aria-label and tabIndex the starter gives the list.

export default function App() {
  const { listRef, meterRef } = useRowNodeMeter();
  const [jumpText, setJumpText] = useState('');

  const handleJump = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
  };

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Payments</h1>
          <p className="subtitle">Ten thousand rows. Draw the twenty that matter.</p>
        </header>

        <form className="jump-form" onSubmit={handleJump}>
          <label className="label" htmlFor="jump">Jump to payment</label>
          <input
            id="jump"
            className="jump"
            type="text"
            inputMode="numeric"
            autoComplete="off"
            value={jumpText}
            onChange={(event) => setJumpText(event.target.value)}
          />
          <button type="submit" className="go">Go</button>
          <p className="jump-status" role="status" />
        </form>

        <div className="list-status">
          <p className="range">Showing 1–10 of {formatNumber(ITEM_COUNT)}</p>
          <span className="row-meter" ref={meterRef} />
        </div>

        <div
          className="viewport"
          ref={listRef}
          role="list"
          aria-label="Payments"
          tabIndex={0}
          style={{ height: VIEWPORT_HEIGHT }}
        >
          <div className="spacer" style={{ height: ITEM_COUNT * ROW_HEIGHT }}>
            {PAYMENTS.map((payment, index) => (
              <div
                key={payment.id}
                className="row"
                role="listitem"
                data-id={payment.id}
                style={{ transform: `translateY(${index * ROW_HEIGHT}px)` }}
              >
                <span className="payment">Payment {formatNumber(payment.id)}</span>
                <span className="amount">{formatMoney(payment.amountCents)}</span>
              </div>
            ))}
          </div>
        </div>
      </section>
    </main>
  );
}

