:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  box-sizing: border-box;
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  place-items: center;
  padding: 24px;
}

.card {
  box-sizing: border-box;
  width: 100%;
  max-width: 560px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  min-width: 0;
  padding: 18px 18px 16px;
  display: grid;
  gap: 14px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.jump-form {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.label {
  font-size: 13px;
  color: #9ca3af;
}

.jump {
  width: 120px;
  background: #0f172a;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 6px 8px;
  font: inherit;
}

.go {
  background: #1e293b;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 6px 12px;
  font: inherit;
  cursor: pointer;
}

.list-status {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  font-size: 13px;
  color: #9ca3af;
}

.range {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.row-meter {
  font-size: 12px;
  color: #9ca3af;
}

.jump-status {
  flex-basis: 100%;
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: #93c5fd;
}

.viewport {
  position: relative;
  /* The checks run in a 1px-wide frame; without a width of its own the list has nothing to scroll there. */
  min-width: 200px;
  overscroll-behavior: contain;
  overflow-y: auto;
  border: 1px solid #1f2937;
  border-radius: 10px;
}

.viewport:focus-visible {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.spacer {
  position: relative;
}

.row {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 36px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 12px;
  border-bottom: 1px solid #1f2937;
  font-size: 14px;
}

.amount {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-variant-numeric: tabular-nums;
  color: #86efac;
}
